'use strict'

/**
 * 
 * @param {string} name 选项名称
 * @param {any} val 输入值
 * @param {object} config 配置
 * @param {object} options 选项，给出限定范围，包括：   
 *    min, max, list, type
 * 
 */

function check_options (options, val) {

  if (options.type) {
    if (options.type === 'array' && !(val instanceof Array)) return false
  
    if (typeof val !== options.type) return false
  }

  if (options.list && (options.list instanceof Array)) {
    if (options.list.indexOf(val) < 0) return false
  }
  else if (options.min !== undefined || options.max !== undefined) {
    if (options.min !== undefined && options.min > val) return false
    if (options.max !== undefined && options.max < val) return false
  }
  else if (options.match && options.match instanceof RegExp) {
    if (!options.match.test(val)) return false
  }
  else if (options.value) {
    if (options.value !== val) return false
  }

  return true

}

exports.autoCheck = (config, name, options, val) => {
  
  let r = check_options(options, val)

  if (!r) {
    
    if (options.default) config[name] = options.default

    return false
  }

  config[name] = val

  return true
}

exports.checkVal = check_options

exports.checkThrow = function (options, val) {
  let r = check_options(options, val)

  if (!r) {
    if (options.error)
      throw error
    else
      throw new Error(options.errmsg || `Illegal data format : ${val}`)
  }

  return true
}

